fn frame(t: i32) {
    host::display::clear(0x0c0d11);
    if host::display::state_get(6) == 0 {
        host::display::state_set(6, 1);
        host::display::state_set(1, 136);
        host::display::state_set(2, 170);
        host::display::state_set(3, 8);
    }
    let period: i32 = host::display::state_get(3);
    let mut phase: i32 = host::display::state_get(4) + 1;
    let mut step: i32 = host::display::state_get(5);
    if phase >= period {
        phase = 0;
        step = (step + 1) & 7;
        host::display::state_set(5, step);
        if ((host::display::state_get(1) >> step) & 1) == 1 {
            host::audio::tone(55, 120, 0);
        }
        if ((host::display::state_get(2) >> step) & 1) == 1 {
            host::audio::noise(25);
        }
    }
    host::display::state_set(4, phase);

    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if px >= 48 && px < 496 && py >= 120 && py < 250 {
            let col: i32 = (px - 48) / 56;
            if col < 8 {
                if py < 180 {
                    host::display::state_set(1, host::display::state_get(1) ^ (1 << col));
                } else if py >= 190 {
                    host::display::state_set(2, host::display::state_get(2) ^ (1 << col));
                }
            }
        }
        if py >= 300 && py < 344 {
            if px >= 48 && px < 108 && period < 24 {
                host::display::state_set(3, period + 2);
            }
            if px >= 140 && px < 200 && period > 4 {
                host::display::state_set(3, period - 2);
            }
        }
    }

    host::display::draw_string(48, 40, "STEP SEQUENCER", 0xffffff, 2);
    host::display::draw_string(48, 100, "KICK", 0xff8866, 1);
    host::display::draw_string(48, 174, "HAT", 0x66ddff, 1);
    let kick: i32 = host::display::state_get(1);
    let hat: i32 = host::display::state_get(2);
    let mut c: i32 = 0;
    while c < 8 {
        let x: i32 = 48 + c * 56;
        if c == step {
            host::display::fill_rect(x, 112, 48, 4, 0xffcc33);
        }
        let mut kcol: i32 = 0x1c212b;
        if ((kick >> c) & 1) == 1 {
            kcol = 0xcc5533;
        }
        host::display::fill_rect(x, 120, 48, 50, kcol);
        let mut hcol: i32 = 0x1c212b;
        if ((hat >> c) & 1) == 1 {
            hcol = 0x3399cc;
        }
        host::display::fill_rect(x, 190, 48, 50, hcol);
        c = c + 1;
    }
    host::display::fill_rect(48, 300, 60, 44, 0x232833);
    host::display::draw_char(72, 314, 45, 0xffffff, 2);
    host::display::fill_rect(140, 300, 60, 44, 0x232833);
    host::display::draw_char(164, 314, 43, 0xffffff, 2);
    host::display::draw_string(240, 306, "STEPS PER MIN", 0x556677, 1);
    host::display::draw_number(240, 322, 3600 / period, 0xffffff, 2);
    host::display::present();
}
